INSERT INTO `grammar_questions` (`id`, `meeting_number`, `question_number`, `question_text`, `correct_answer`, `example_id`, `example_en`, `vocab`, `created_at`, `updated_at`, `tense`, `structure`, `formula`, `example`, `vocabulary`, `section`) VALUES
(561, 11, 1, 'Universitas itu menambah program penelitian, karena kebutuhan energi terbarukan semakin mendesak.', 'The university added research programs, because the need for renewable energy is increasingly urgent', NULL, 'I stayed home, for it was raining.', '{"Renewable energy":"Energi terbarukan","Increasingly":"Semakin","Urgent":"Mendesak","Research program":"Program penelitian"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(562, 11, 2, 'Kota itu membangun jalur sepeda, dan warganya mulai beralih dari kendaraan bermotor.', 'The city built bicycle lanes, and its residents began to switch from motor vehicles', NULL, 'She likes apples, and he likes oranges.', '{"Bicycle lane":"Jalur sepeda","Resident":"Warga","Switch":"Beralih","Motor vehicle":"Kendaraan bermotor"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(563, 11, 3, 'Pusat studi tersebut tidak memiliki cukup dana, maupun menerima dukungan dari organisasi internasional.', 'The study center does not have enough funds, nor does it receive support from international organizations', NULL, 'He doesn\'t eat meat, nor does he drink milk.', '{"Fund":"Dana","Receive":"Menerima","Support":"Dukungan","International organization":"Organisasi internasional"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(564, 11, 4, 'Para ilmuwan ingin menguji teori baru, tetapi alat laboratorium mereka belum memadai.', 'Scientists want to test new theories, but their laboratory equipment is not yet adequate', NULL, 'I want to go, but I am tired.', '{"Test":"Menguji","Theory":"Teori","Equipment":"Peralatan","Adequate":"Memadai"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(565, 11, 5, 'Mahasiswa bisa memilih fokus pada biologi laut, atau mereka dapat menekuni bidang energi berkelanjutan.', 'Students can choose to focus on marine biology, or they can pursue the field of sustainable energy', NULL, 'You can study now, or you can sleep.', '{"Focus":"Fokus","Marine biology":"Biologi laut","Pursue":"Menekuni","Sustainable energy":"Energi berkelanjutan"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(566, 11, 6, 'Tim peneliti bekerja siang malam, namun hasil yang mereka peroleh masih belum stabil.', 'The research team works day and night, yet the results they obtain are still unstable', NULL, 'It is sunny, yet it is cold.', '{"Obtain":"Memperoleh","Result":"Hasil","Unstable":"Tidak stabil","Research team":"Tim peneliti"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(567, 11, 7, 'Pemerintah berkomitmen mengurangi emisi, sehingga mereka menetapkan regulasi yang lebih ketat.', 'The government is committed to reducing emissions, so they established stricter regulations', NULL, 'I was hungry, so I ate.', '{"Committed":"Berkomitmen","Reduce":"Mengurangi","Emission":"Emisi","Establish":"Menetapkan","Regulation":"Regulasi"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(568, 11, 8, 'Festival budaya berlangsung meriah, karena masyarakat ingin melestarikan tradisi leluhur.', 'The cultural festival took place festively, because the community wants to preserve ancestral traditions', NULL, 'He is happy, because he won.', '{"Take place":"Berlangsung","Festively":"Meriah","Preserve":"Melestarikan","Ancestral tradition":"Tradisi leluhur"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(569, 11, 9, 'Bandara itu meningkatkan kapasitas penerbangan, dan infrastruktur pendukung juga diperbaiki.', 'The airport increased flight capacity, and supporting infrastructure was also improved', NULL, 'I bought a pen, and I bought a book.', '{"Increase":"Meningkatkan","Flight capacity":"Kapasitas penerbangan","Infrastructure":"Infrastruktur","Improve":"Diperbaiki"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(570, 11, 10, 'Perusahaan itu tidak mengurangi produksi plastik sekali pakai, maupun mencoba mencari alternatif ramah lingkungan.', 'The company does not reduce single-use plastic production, nor does it try to find environmentally friendly alternatives', NULL, 'She didn\'t call, nor did she text.', '{"Reduce":"Mengurangi","Single-use":"Sekali pakai","Production":"Produksi","Environmentally friendly":"Ramah lingkungan"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(571, 11, 11, 'Jalur kereta cepat telah dibuka, tetapi harga tiketnya masih dianggap terlalu tinggi.', 'The high-speed rail line has been opened, but the ticket price is still considered too high', NULL, 'The car is fast, but it is expensive.', '{"High-speed rail":"Kereta cepat","Line":"Jalur","Ticket price":"Harga tiket","Consider":"Dianggap"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(572, 11, 12, 'Wisatawan dapat mengunjungi taman nasional, atau mereka bisa mengikuti program konservasi komunitas.', 'Tourists can visit national parks, or they can join community conservation programs', NULL, 'We can go to the beach, or we can go to the mountains.', '{"Tourist":"Wisatawan","Visit":"Mengunjungi","National park":"Taman nasional","Join":"Mengikuti","Conservation":"Konservasi"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(573, 11, 13, 'Data ilmiah telah terkumpul selama bertahun-tahun, namun interpretasinya tetap menimbulkan perdebatan.', 'Scientific data has been collected for years, yet its interpretation still causes debate', NULL, 'He is rich, yet he is unhappy.', '{"Collect":"Terkumpul","Interpretation":"Interpretasi","Cause":"Menimbulkan","Debate":"Perdebatan"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(574, 11, 14, 'Program pendidikan digital berkembang pesat, sehingga akses pembelajaran menjadi lebih merata.', 'Digital education programs are developing rapidly, so learning access becomes more equitable', NULL, 'It was late, so we went home.', '{"Develop":"Berkembang","Rapidly":"Pesat","Access":"Akses","Equitable":"Merata"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(575, 11, 15, 'Desa itu menjaga hutan adatnya, karena mereka percaya hutan adalah sumber kehidupan.', 'The village protects its customary forest, because they believe the forest is the source of life', NULL, 'She smiled, because she was happy.', '{"Protect":"Menjaga","Customary forest":"Hutan adat","Believe":"Percaya","Source of life":"Sumber kehidupan"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, NULL),
(576, 12, 1, 'Saya akan menunggumu di sini sampai kamu menyelesaikan tugasmu.', 'I will wait for you here until you finish your task', NULL, NULL, '{"Wait":{"id":"Menunggu","pos":"(v)"},"Task":{"id":"Tugas","pos":"(n)"},"Finish":{"id":"Menyelesaikan","pos":"(v)"},"Here":{"id":"Di sini","pos":"(adv)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'until (sampai)', '{"id":"Kami belajar sampai perpustakaan tutup.","en":"We studied until the library closed."}', NULL, 'default'),
(577, 12, 2, 'Piramida Mesir dibangun ketika peradaban kuno masih sangat kuat.', 'The Egyptian pyramids were built when the ancient civilization was still very strong', NULL, NULL, '{"Ancient":{"id":"Kuno","pos":"(adj)"},"Pyramid":{"id":"Piramida","pos":"(n)"},"Civilization":{"id":"Peradaban","pos":"(n)"},"Collapse":{"id":"Runtuh","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'when (ketika)', '{"id":"Dia menelepon ketika saya sedang tidur.","en":"He called when I was sleeping."}', NULL, 'default'),
(578, 12, 3, 'Penyebaran ilmu pengetahuan terbatas, sebelum mesin cetak Gutenberg diperkenalkan di Eropa.', 'The spread of knowledge was limited, before the Gutenberg printing press was introduced in Europe', NULL, NULL, '{"Spread":{"id":"Penyebaran","pos":"(n)"},"Knowledge":{"id":"Ilmu pengetahuan","pos":"(n)"},"Limited":{"id":"Terbatas","pos":"(adj)"},"Printing press":{"id":"Mesin cetak","pos":"(n)"},"Introduce":{"id":"Diperkenalkan","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'before (sebelum)', '{"id":"Cuci tangan sebelum kamu makan.","en":"Wash your hands before you eat."}', NULL, 'default'),
(579, 12, 4, 'Pola kerja manusia berubah drastis setelah revolusi industri dimulai di Inggris.', 'Human work patterns changed drastically after the industrial revolution began in England', NULL, NULL, '{"Pattern":{"id":"Pola","pos":"(n)"},"Work":{"id":"Kerja","pos":"(n)"},"Change":{"id":"Berubah","pos":"(v)"},"Drastically":{"id":"Drastis","pos":"(adv)"},"Industrial revolution":{"id":"Revolusi industri","pos":"(n)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'after (setelah)', '{"id":"Dia pergi setelah rapat selesai.","en":"He left after the meeting ended."}', NULL, 'default'),
(580, 12, 5, 'Pemahaman tentang tata surya semakin akurat sejak astronomi berkembang sebagai ilmu modern.', 'Understanding of the solar system became increasingly accurate since astronomy developed as a modern science', NULL, NULL, '{"Understanding":{"id":"Pemahaman","pos":"(n)"},"Solar system":{"id":"Tata surya","pos":"(n)"},"Accurate":{"id":"Akurat","pos":"(adj)"},"Astronomy":{"id":"Astronomi","pos":"(n)"},"Modern":{"id":"Modern","pos":"(adj)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'since (sejak)', '{"id":"Saya tinggal di sini sejak tahun 2020.","en":"I have lived here since 2020."}', NULL, 'default'),
(581, 12, 6, 'Epidemi luas sering terjadi sampai vaksin berhasil ditemukan.', 'Widespread epidemics often occurred until vaccines were successfully discovered', NULL, NULL, '{"Epidemic":{"id":"Epidemi","pos":"(n)"},"Widespread":{"id":"Luas","pos":"(adj)"},"Occur":{"id":"Terjadi","pos":"(v)"},"Vaccine":{"id":"Vaksin","pos":"(n)"},"Discover":{"id":"Ditemukan","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'until (sampai)', '{"id":"Tunggu sampai hujan berhenti.","en":"Wait until the rain stops."}', NULL, 'default'),
(582, 12, 7, 'Produktivitas industri meningkat signifikan segera setelah listrik diperkenalkan di kota besar.', 'Industrial productivity increased significantly as soon as electricity was introduced in big cities', NULL, NULL, '{"Productivity":{"id":"Produktivitas","pos":"(n)"},"Industrial":{"id":"Industri","pos":"(adj)"},"Increase":{"id":"Meningkat","pos":"(v)"},"Significantly":{"id":"Signifikan","pos":"(adv)"},"Electricity":{"id":"Listrik","pos":"(n)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'time', 'as soon as (segera setelah)', '{"id":"Hubungi saya segera setelah kamu tiba.","en":"Contact me as soon as you arrive."}', NULL, 'default'),
(583, 12, 8, 'Banyak masyarakat tinggal di sekitar gunung berapi karena tanah di sekitarnya sangat subur.', 'Many communities live around volcanoes because the surrounding soil is very fertile', NULL, NULL, '{"Community":{"id":"Masyarakat","pos":"(n)"},"Volcano":{"id":"Gunung berapi","pos":"(n)"},"Surrounding":{"id":"Sekitar","pos":"(adj)"},"Soil":{"id":"Tanah","pos":"(n)"},"Fertile":{"id":"Subur","pos":"(adj)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'cause', 'because (karena)', '{"id":"Dia tidak datang karena dia sakit.","en":"He did not come because he was sick."}', NULL, 'default'),
(584, 12, 9, 'Teori heliosentris akhirnya diterima sebagai dasar ilmu astronomi, meskipun awalnya ditolak.', 'The heliocentric theory was finally accepted as the basis of astronomy, although it was initially rejected', NULL, NULL, '{"Heliocentric":{"id":"Heliosentris","pos":"(adj)"},"Theory":{"id":"Teori","pos":"(n)"},"Accept":{"id":"Diterima","pos":"(v)"},"Basis":{"id":"Dasar","pos":"(n)"},"Reject":{"id":"Ditolak","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'contrast', 'although (meskipun)', '{"id":"Dia tetap bekerja meskipun dia lelah.","en":"He kept working although he was tired."}', NULL, 'default'),
(585, 12, 10, 'Para penjelajah berhasil menyeberangi Samudra Pasifik, walaupun lautannya sangat luas.', 'Explorers successfully crossed the Pacific Ocean, although the ocean was very vast', NULL, NULL, '{"Explorer":{"id":"Penjelajah","pos":"(n)"},"Successfully":{"id":"Berhasil","pos":"(adv)"},"Cross":{"id":"Menyeberangi","pos":"(v)"},"Ocean":{"id":"Samudra","pos":"(n)"},"Vast":{"id":"Luas","pos":"(adj)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'contrast', 'although (walaupun)', '{"id":"Dia lulus walaupun jarang belajar.","en":"He passed although he rarely studied."}', NULL, 'default'),
(586, 12, 11, 'Keanekaragaman hayati dapat bertahan jika hutan hujan tropis tetap terjaga.', 'Biodiversity can survive if tropical rainforests remain preserved', NULL, NULL, '{"Biodiversity":{"id":"Keanekaragaman hayati","pos":"(n)"},"Survive":{"id":"Bertahan","pos":"(v)"},"Tropical":{"id":"Tropis","pos":"(adj)"},"Rainforest":{"id":"Hutan hujan","pos":"(n)"},"Preserve":{"id":"Terjaga","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'condition', 'if (jika)', '{"id":"Jika hujan, saya akan di rumah.","en":"If it rains, I will stay home."}', NULL, 'default'),
(587, 12, 12, 'Populasi ikan menurun drastis kecuali jika konservasi laut dilakukan secara serius.', 'Fish populations decline drastically unless marine conservation is carried out seriously', NULL, NULL, '{"Population":{"id":"Populasi","pos":"(n)"},"Decline":{"id":"Menurun","pos":"(v)"},"Marine":{"id":"Laut","pos":"(adj)"},"Conservation":{"id":"Konservasi","pos":"(n)"},"Carry out":{"id":"Dilakukan","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'condition', 'unless (kecuali jika)', '{"id":"Kamu akan gagal kecuali jika kamu belajar.","en":"You will fail unless you study."}', NULL, 'default'),
(588, 12, 13, 'Teknologi satelit dikembangkan agar komunikasi antarnegara menjadi lebih mudah.', 'Satellite technology was developed so that communication between countries became easier', NULL, NULL, '{"Satellite":{"id":"Satelit","pos":"(n)"},"Technology":{"id":"Teknologi","pos":"(n)"},"Develop":{"id":"Dikembangkan","pos":"(v)"},"Communication":{"id":"Komunikasi","pos":"(n)"},"Easier":{"id":"Lebih mudah","pos":"(adj)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'purpose', 'so that (agar)', '{"id":"Dia belajar keras agar bisa lulus.","en":"He studies hard so that he can pass."}', NULL, 'default'),
(589, 12, 14, 'Interaksi budaya meningkat pesat di mana pun jalur perdagangan internasional terbuka.', 'Cultural interaction increased rapidly wherever international trade routes opened', NULL, NULL, '{"Interaction":{"id":"Interaksi","pos":"(n)"},"Cultural":{"id":"Budaya","pos":"(adj)"},"Trade route":{"id":"Jalur perdagangan","pos":"(n)"},"International":{"id":"Internasional","pos":"(adj)"},"Open":{"id":"Terbuka","pos":"(v)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'place', 'wherever (di mana pun)', '{"id":"Dia pergi ke mana pun dia mau.","en":"He goes wherever he wants."}', NULL, 'default'),
(590, 12, 15, 'Kota Petra terlihat seakan keluar dari tebing batu, seolah-olah arsitekturnya terukir secara alami.', 'The city of Petra looks as if it emerges from the rock cliffs, as if its architecture was carved naturally', NULL, NULL, '{"Emerge":{"id":"Keluar","pos":"(v)"},"Rock cliff":{"id":"Tebing batu","pos":"(n)"},"Architecture":{"id":"Arsitektur","pos":"(n)"},"Carve":{"id":"Terukir","pos":"(v)"},"Naturally":{"id":"Secara alami","pos":"(adv)"}}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, 'manner', 'as if (seolah-olah)', '{"id":"Dia bertingkah seolah-olah dia raja.","en":"He acts as if he is a king."}', NULL, 'default'),
(591, 12, 100, 'Perkembangan teknologi terus mengalami percepatan sejak revolusi industri dimulai di Eropa. Inovasi dalam bidang komunikasi semakin penting ketika mesin telegraf diperkenalkan pada abad ke-19. Internet menjadi tonggak besar, karena ia menghubungkan miliaran manusia dalam waktu nyata. Penyebaran informasi menjadi semakin cepat, walaupun masih terdapat kesenjangan digital di beberapa wilayah. Penelitian ilmiah pun berkembang pesat, agar masyarakat dapat memperoleh solusi atas tantangan global yang semakin kompleks.', 'Technological development has continued to accelerate since the industrial revolution began in Europe. Innovation in the field of communication became increasingly important when the telegraph machine was introduced in the 19th century. The internet became a major milestone, because it connects billions of humans in real time. The spread of information became increasingly fast, although there is still a digital divide in some regions. Scientific research also developed rapidly, so that society can obtain solutions to increasingly complex global challenges.', NULL, NULL, '{"Technological development":"Perkembangan teknologi","Accelerate":"Mengalami percepatan","Industrial revolution":"Revolusi industri","Innovation":"Inovasi","Communication":"Komunikasi","Telegraph machine":"Mesin telegraf","Milestone":"Tonggak besar","Connect":"Menghubungkan","Real time":"Waktu nyata","Spread of information":"Penyebaran informasi","Digital divide":"Kesenjangan digital","Scientific research":"Penelitian ilmiah","Solution":"Solusi","Challenge":"Tantangan","Complex":"Kompleks"}', '2026-03-16 02:53:41', '2026-03-16 02:53:41', NULL, NULL, NULL, NULL, NULL, 'paragraph'),
(592, 11, 100, 'Pendidikan digital semakin berkembang karena teknologi internet sudah menjangkau banyak daerah. Sekolah mulai menggunakan platform daring dan guru mendapatkan pelatihan khusus untuk mengajar secara interaktif. Tidak semua siswa memiliki perangkat memadai, maupun koneksi internet yang stabil di rumah mereka. Banyak universitas menawarkan kursus online, tetapi masih ada hambatan dalam penerapan di daerah terpencil. Mahasiswa bisa mengikuti kelas tatap muka atau memilih pembelajaran jarak jauh sesuai kebutuhan. Sistem ini memberi fleksibilitas besar, namun tantangan kesenjangan akses masih perlu diatasi. Transformasi pendidikan berbasis digital terus berjalan, sehingga kesempatan belajar menjadi lebih terbuka untuk semua kalangan.', 'Digital education is increasingly developing because internet technology has reached many areas. Schools are starting to use online platforms and teachers are getting special training to teach interactively. Not all students have adequate devices, nor do they have stable internet connections at their homes. Many universities offer online courses, but there are still obstacles in implementation in remote areas. Students can attend face-to-face classes or choose distance learning according to their needs. This system provides great flexibility, yet the challenge of access gaps still needs to be addressed. The digital-based education transformation continues, so learning opportunities become more open to all groups.', NULL, NULL, '{"Digital education":"Pendidikan digital","Increasingly":"Semakin","Online platform":"Platform daring","Interactively":"Secara interaktif","Adequate":"Memadai","Stable":"Stabil","Obstacle":"Hambatan","Remote areas":"Daerah terpencil","Face-to-face":"Tatap muka","Distance learning":"Pembelajaran jarak jauh","Flexibility":"Fleksibilitas","Access gap":"Kesenjangan akses","Transformation":"Transformasi"}', '2026-03-16 02:54:08', '2026-03-16 02:54:08', NULL, NULL, NULL, NULL, NULL, 'paragraph'),
(944, 9, 1, 'Di perairan tropis Indonesia, para ilmuwan baru-baru ini menemukan spesies koral langka yang memiliki ketahanan luar biasa terhadap perubahan suhu. Penemuan ini berawal dari pengamat pasif yang memperhatikan pola pertumbuhan unik di sekitar terumbu karang. Menggunakan sistem pemantauan canggih, departemen lingkungan mengonfirmasi bahwa koral tersebut dapat bertahan hidup meskipun suhu laut meningkat secara signifikan. Kerja lapangan dilakukan selama enam bulan, melibatkan masyarakat lokal dan staf senior dari berbagai universitas. Ekspedisi tersebut juga mengumpulkan data historis untuk dianalisis lebih lanjut. Sampel arsip dari tahun-tahun sebelumnya menunjukkan bahwa spesies ini telah ada sejak lama, namun baru sekarang teridentifikasi secara resmi. Saat ini, draf kebijakan laut yang komprehensif sedang disusun untuk melindungi habitat koral tersebut. Setelah revisi selesai, dokumen itu akan disimpan di gudang data nasional. Penemuan ini diharapkan dapat berubah menjadi pusat inovasi kolaboratif bagi penelitian kelautan di masa depan.', 'In Indonesia\'s tropical waters, scientists recently discovered a rare coral species that has extraordinary resilience to temperature changes. This discovery began with passive observers who noticed unique growth patterns around the coral reefs. Using sophisticated monitoring systems, the environmental department confirmed that the coral could survive even though sea temperatures increased significantly. Fieldwork was conducted for six months, involving local communities and senior staff from various universities. The expedition also collected historical data to be analyzed further. Archival samples from previous years showed that this species had existed for a long time, yet it is only now officially identified. Currently, a comprehensive marine policy draft is being drafted to protect the coral habitat. After the revision is complete, the document will be stored in the national data warehouse. This discovery is expected to transform into a collaborative innovation hub for future marine research.', NULL, NULL, '{"Resilience":"Ketahanan","Tropical waters":"Perairan tropis","Passive observer":"Pengamat pasif","Sophisticated monitoring system":"Sistem pemantauan canggih","Environmental department":"Departemen lingkungan","Fieldwork":"Kerja lapangan","Local community":"Masyarakat lokal","Senior staff":"Staf senior","Expedition":"Ekspedisi","Historical data":"Data historis","Analyze":"Dianalisis","Archival sample":"Sampel arsip","Marine policy draft":"Draf kebijakan laut","Comprehensive":"Komprehensif","Revision":"Revisi","Data warehouse":"Gudang data","Transform":"Berubah","Collaborative innovation hub":"Pusat inovasi kolaboratif"}', '2026-03-16 02:55:25', '2026-03-16 02:55:25', NULL, NULL, NULL, NULL, NULL, 'paragraph'),
(945, 10, 1, 'Asia adalah benua terbesar di dunia.', 'Asia is the biggest continent in the world', 'Rusia adalah negara terluas di dunia.', 'Russia is the largest country in the world.', '{"Continent":{"id":"Benua","pos":"(n)"},"Big":{"id":"Besar","pos":"(adj)"},"In the world":{"id":"Di dunia","pos":"(phrase)"}}', '2026-03-16 02:55:25', '2026-03-16 02:55:25', NULL, 'Superlative', NULL, NULL, NULL, NULL),
(946, 10, 2, 'Gunung tertinggi di dunia adalah Gunung Everest.', 'The highest mountain in the world is Mount Everest', 'Sungai Nil adalah sungai terpanjang di dunia.', 'The Nile is the longest river in the world.', '{"Mountain":{"id":"Gunung","pos":"(n)"},"High":{"id":"Tinggi","pos":"(adj)"},"In the world":{"id":"Di dunia","pos":"(phrase)"}}', '2026-03-16 02:55:25', '2026-03-16 02:55:25', NULL, 'Superlative', NULL, NULL, NULL, NULL),
