(1810, 6, 9, 'Dikembangkan di laboratorium membuat virus ini berbahaya.', 'Being developed in a laboratory makes this virus dangerous', NULL, NULL, '{"Developed":{"id":"Dikembangkan","pos":"(v)"},"Laboratory":{"id":"Laboratorium","pos":"(n)"},"Virus":{"id":"Virus","pos":"(n)"},"Dangerous":{"id":"Berbahaya","pos":"(adj)"}}', '2026-03-16 03:04:48', '2026-03-16 03:04:48', NULL, NULL, NULL, '{"id":"Dibuat di rumah membuatnya spesial.","en":"Being made at home makes it special."}', NULL, 'gerund'),
(1811, 6, 10, 'Banyak proyek beresiko ditinggalkan oleh pemerintah.', 'Many risky projects are abandoned by the government', NULL, NULL, '{"Risky":{"id":"Beresiko","pos":"(adj)"},"Project":{"id":"Proyek","pos":"(n)"},"Abandoned":{"id":"Ditinggalkan","pos":"(v)"},"Government":{"id":"Pemerintah","pos":"(n)"}}', '2026-03-16 03:04:48', '2026-03-16 03:04:48', NULL, NULL, NULL, '{"id":"Rumah tua ditinggalkan.","en":"Old houses are abandoned."}', NULL, 'gerund'),
(1812, 6, 11, 'Sistem transportasi tua ini tetap digunakan oleh masyarakat.', 'This old transportation system is still used by society', NULL, NULL, '{"Transportation system":{"id":"Sistem transportasi","pos":"(n)"},"Old":{"id":"Tua","pos":"(adj)"},"Used":{"id":"Digunakan","pos":"(v)"},"Society":{"id":"Masyarakat","pos":"(n)"}}', '2026-03-16 03:04:48', '2026-03-16 03:04:48', NULL, NULL, NULL, '{"id":"Metode lama masih digunakan.","en":"Old methods are still used."}', NULL, 'gerund'),
(1813, 6, 12, 'Organisasi ini berhenti dipercayai oleh masyarakat.', 'This organization stops being trusted by society', NULL, NULL, '{"Organization":{"id":"Organisasi","pos":"(n)"},"Stop":{"id":"Berhenti","pos":"(v)"},"Trusted":{"id":"Dipercayai","pos":"(v)"},"Society":{"id":"Masyarakat","pos":"(n)"}}', '2026-03-16 03:04:48', '2026-03-16 03:04:48', NULL, NULL, NULL, '{"id":"Dia berhenti dicintai.","en":"He stops being loved."}', NULL, 'gerund');
